pub extern "C" fn kernel_acc() -> f64 {
    let dt = core::hint::black_box(1.0f64 / 64.0);
    let (mut y, mut vy) = (core::hint::black_box(3.0f64), core::hint::black_box(0.0f64));
    let mut acc = 0.0f64;
    for i in 0..640 {
        vy = vy - 8.0 * dt;
        y = y + vy * dt;
        if y < 0.5 {
            y = 0.5 + (0.5 - y);
            vy = 0.0 - vy * 0.8;
        }
        acc = acc + (y * y + vy * vy).sqrt() / (i as f64 + 1.0);
    }
    acc
}

