// Iterate any collection by shared reference, whatever its concrete type.
fn sum_all<C>(c: C) -> f64 where for<'a> &'a C: IntoIterator<Item = &'a f64> {
    let mut s = 0.0;
    for x in &c { s += *x; }
    s
