// Two laws, one generic driver, two monomorphic exports: the trait lives
// inside the crate; the ABI stays plain extern "C" functions.
trait Law {
    const GRAVITY_SCALE: f64;
    fn step(&mut self, body: &mut [f64; 3]) -> bool;
